501:     // アプリ状態（すべてスプレッドシートから動的に取得・更新されます）
502:     let state = {
503:       siteCode: "",
504:       customer: "",
505:       dateString: "",
506:       currentLotCount: 0,
507:       currentOrderCount: 0,
508:       customers: [],
509:       siteCodes: [],
