511:       failureParts: [],
512:       printerIp: "192.168.11.50",
513:       scannedDataList: [],
514:       // カメラ関連状態 (nfcQrWriter_v01 準拠)
515:       isCameraRunning: false,
516:       html5QrCode: null,
517:       currentCameraIndex: 0,
518:       availableCameras: [],
519:       isMirrored: false
520:     };
521: 
522:     // ==========================================
523:     // Web Audio API & バイブレーション (nfcQrWriter_v01 準拠)
524:     // ==========================================
525:     const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
526: 
527:     function playSound(type) {
528:       if (audioCtx.state === 'suspended') {
529:         audioCtx.resume();
530:       }
531:       const osc = audioCtx.createOscillator();
532:       const gain = audioCtx.createGain();
533:       osc.connect(gain);
534:       gain.connect(audioCtx.destination);
