612:     // GAS通信ラッパー (google.script.run / fetch GET・POST 両対応)
613:     // ==========================================
614:     function callGasApi(action, params = {}) {
615:       return new Promise((resolve, reject) => {
616:         // 1. GAS Web App環境内（google.script.run が利用可能な場合）
617:         if (typeof google !== "undefined" && google.script && google.script.run) {
618:           if (action === "init") {
619:             google.script.run
620:               .withSuccessHandler(res => {
621:                 if (res && res.status === "success") resolve(res);
622:                 else reject(new Error(res ? res.message : "取得エラー"));
623:               })
624:               .withFailureHandler(err => reject(new Error(err.message || err)))
625:               .apiInit();
626:             return;
627:           } else if (action === "start") {
628:             google.script.run
629:               .withSuccessHandler(res => {
630:                 if (res && res.status === "success") resolve(res);
631:                 else reject(new Error(res ? res.message : "取得エラー"));
632:               })
633:               .withFailureHandler(err => reject(new Error(err.message || err)))
634:               .apiStart(params);
635:             return;
636:           } else if (action === "finish") {
637:             google.script.run
638:               .withSuccessHandler(res => {
639:                 if (res && res.status === "success") resolve(res);
640:                 else reject(new Error(res ? res.message : "更新エラー"));
641:               })
642:               .withFailureHandler(err => reject(new Error(err.message || err)))
643:               .apiFinish(params);
644:             return;
645:           }
646:         }
647: 
648:         // 2. 外部ブラウザからの fetch 通信 (CORS / リダイレクト安全対応)
649:         if (!GAS_URL || GAS_URL.includes("ここに")) {
650:           reject(new Error("GAS_URLが設定されていません。"));
651:           return;
652:         }
653: 
654:         if (action === "init" || action === "start") {
655:           // GETリクエストで高速・安全に取得
656:           const queryParams = new URLSearchParams({ action: action, ...params });
657:           const targetUrl = `${GAS_URL}?${queryParams.toString()}`;
658: 
659:           fetch(targetUrl, {
660:             method: "GET",
661:             mode: "cors",
662:             redirect: "follow"
663:           })
664:           .then(res => res.json())
665:           .then(json => {
666:             if (json.status !== "success") {
667:               throw new Error(json.message || "データ取得エラー");
668:             }
669:             resolve(json);
670:           })
671:           .catch(err => {
672:             // GET失敗時のPOSTフォールバック
673:             console.warn("GET request failed, trying POST fallback:", err);
674:             fetch(GAS_URL, {
675:               method: "POST",
676:               headers: { "Content-Type": "text/plain;charset=utf-8" },
677:               body: JSON.stringify({ action: action, ...params })
678:             })
679:             .then(res => res.text())
680:             .then(text => {
681:               try {
682:                 const json = JSON.parse(text);
683:                 if (json.status !== "success") throw new Error(json.message || "処理エラー");
684:                 resolve(json);
685:               } catch (e) {
686:                 throw new Error("GAS通信エラー: " + (e.message || text));
687:               }
688:             })
689:             .catch(reject);
690:           });
691: 
692:         } else {
693:           // finish 等の更新リクエスト (POST)
694:           fetch(GAS_URL, {
695:             method: "POST",
696:             headers: { "Content-Type": "text/plain;charset=utf-8" },
697:             body: JSON.stringify({ action: action, ...params })
698:           })
699:           .then(res => res.text())
700:           .then(text => {
701:             try {
702:               const json = JSON.parse(text);
703:               if (json.status !== "success") {
704:                 throw new Error(json.message || "処理エラー");
705:               }
706:               resolve(json);
707:             } catch (e) {
708:               if (text.includes("<!DOCTYPE") || text.includes("<html") || text.includes("Google Accounts")) {
709:                 throw new Error("GASアクセス権限エラー: デプロイ設定で「アクセスできるユーザー」を「全員 (Anyone)」に設定してください。");
710:               }
711:               throw new Error(e.message || "不正なレスポンスを受信しました");
712:             }
713:           })
714:           .catch(reject);
715:         }
716:       });
717:     }
