// ==========================================
// 3. プリンター出力 (Brother QL-820NWB - b-PAC連携)
// ==========================================
async function printLabel(record) {
  console.log(`[PRINT] ロット:${record.lotSeqNumber}, 受注:${record.orderNumber}, SN:${record.sn}, ID:${record.deviceId}, 症状:${record.symptom}`);

  try {
    // b-PAC クライアントAPIがロードされているか確認
    if (typeof bpac === 'undefined') {
      console.warn("b-PAC SDK (bpac.js) が見つかりません。コンソール出力のみ行います。");
      return;
    }

    // TODO: 実際のlbxファイルのパスに書き換えてください
    const templatePath = "C:\\KiriPlayPark\\label.lbx"; 

    const doc = bpac.IDocument;
    const isOpen = await doc.Open(templatePath);

    if (isOpen) {
      // P-touch Editor で設定したオブジェクト名(参照名)にデータをセット
      let objLot = await doc.GetObject("txtLot");
      if (objLot) await objLot.SetText(record.lotSeqNumber);

      let objSN = await doc.GetObject("txtSN");
      if (objSN) await objSN.SetText(record.sn);

      let objID = await doc.GetObject("txtID");
      if (objID) await objID.SetText(record.deviceId || "");

      let objSymptom = await doc.GetObject("txtSymptom");
      if (objSymptom) await objSymptom.SetText(record.symptom || "");

      // プリンタ名を明示的に指定する場合（オプション）
      // await doc.SetPrinter("Brother QL-820NWB", true); 

      // 印刷の実行
      await doc.StartPrint("", 0);
      await doc.PrintOut(1, 0); // 1枚印刷
      await doc.EndPrint();
      await doc.Close();

      console.log(`[PRINT SUCCESS] ${record.sn} のラベルを印刷しました。`);
    } else {
      console.error("テンプレートファイルが開けませんでした: " + templatePath);
      showLog("scan-log", "印刷エラー: テンプレートが見つかりません。");
    }
  } catch (e) {
    console.error("印刷中にエラーが発生しました:", e);
    showLog("scan-log", "印刷エラー: " + e.message);
  }
}

